<template><view><SiteHeader active="saved"/><view class="wrap"><text class="kicker">YOUR WORKSPACE</text><text class="title">我的收藏</text><text class="subtitle">保存感兴趣的文章和线下活动，方便下次继续看。</text><text class="hint">收藏和研究笔记仅保存在当前设备和当前端，不会自动同步到其他设备。</text><view class="tabs"><button :class="{on:tab==='article'}" @click="tab='article'">文章 {{savedArticles.length}}</button><button :class="{on:tab==='event'}" @click="tab='event'">线下活动 {{savedEvents.length}}</button></view><view v-if="tab==='article'"><view v-for="a in savedArticles" :key="a.id" class="row" @click="openArticle(a)"><text class="kind">{{a.kind || '分享'}} · {{a.author}}</text><text class="name">{{a.title}}</text><text class="summary">{{a.overview||a.summary}}</text><view class="row-bottom"><text>查看导读 →</text><text @click.stop="remove('article',a)">取消收藏</text></view></view><view v-if="!savedArticles.length" class="empty">还没有收藏文章，可以先去发现页看看。<button @click="goDiscover">去发现</button></view></view><view v-else><view v-for="e in savedEvents" :key="e.id" class="row"><text class="kind">{{e.city}} · {{e.typeText || '活动'}}</text><text class="name">{{e.name}}</text><text class="summary">{{e.summary||e.description}}</text><view class="row-bottom"><text @click="goEvents">在线下活动页查看 →</text><text @click="remove('event',e)">取消收藏</text></view></view><view v-if="!savedEvents.length" class="empty">还没有收藏线下活动。<button @click="goEvents">查看线下活动</button></view></view></view><CampFooter/></view></template>
<script setup>
import {computed,ref} from 'vue';import {onShow} from '@dcloudio/uni-app';
import SiteHeader from '../../components/SiteHeader.vue';import CampFooter from '../../components/CampFooter.vue';
import {articles,events} from '../../data/content.js';import {getSaved,setSaved} from '../../data/storage.js';
const tab=ref('article'),saved=ref([]);onShow(()=>{saved.value=getSaved()});
const savedArticles=computed(()=>articles.filter(a=>saved.value.includes(`article:${a.id}`)));
const savedEvents=computed(()=>events.filter(e=>saved.value.includes(`event:${e.id}`)));
function remove(t,item){saved.value=saved.value.filter(k=>k!==`${t}:${item.id}`);setSaved(saved.value)}
function openArticle(a){uni.navigateTo({url:`/pages/article/index?id=${encodeURIComponent(a.id)}`})}
function goDiscover(){uni.redirectTo({url:'/pages/discover/index'})}function goEvents(){uni.redirectTo({url:'/pages/events/index'})}
</script>
<style scoped>.wrap{max-width:1050px;margin:auto;padding:48rpx 28rpx;color:#173d2b}.kicker{display:block;color:#8ca679;font-size:22rpx;letter-spacing:2rpx}.title{display:block;font-size:52rpx;font-weight:750;margin:12rpx 0}.subtitle,.hint{display:block;color:#6c8570;font-size:26rpx;line-height:1.8}.hint{font-size:22rpx;color:#94a48f}.tabs{display:flex;gap:12rpx;margin:30rpx 0}.tabs button{margin:0;background:#eef4e9;color:#56745b;font-size:25rpx;line-height:2.7}.tabs button.on{background:#235039;color:#fff}.row{background:#fff;border:1px solid #e1e9dc;border-radius:9rpx;padding:25rpx;margin-bottom:12rpx}.kind{font-size:22rpx;color:#8ca087}.name,.summary{display:block}.name{font-size:29rpx;font-weight:700;line-height:1.5;margin:12rpx 0}.summary{font-size:24rpx;line-height:1.7;color:#708674}.row-bottom{display:flex;justify-content:space-between;color:#5c865f;font-size:23rpx;margin-top:18rpx}.empty{padding:55rpx;color:#859a83;background:#fafcf8}.empty button{margin:20rpx 0 0;display:inline-block;background:#dcebd3;color:#355d3f;font-size:24rpx;line-height:2.8}</style>
